import Foundation
import NIO
import NIOHTTP1

// Swift database driver - handles user-uploaded schema migration files
// Processes .dbmigration files uploaded via HTTP multipart

struct MigrationConfig {
    let baseDirectory: String
    let allowedExtensions: Set<String>
    let maxFileSize: Int

    static let `default` = MigrationConfig(
        baseDirectory: "/var/lib/dbdriver/migrations",
        allowedExtensions: [".dbmigration", ".dbschema"],
        maxFileSize: 1024 * 1024
    )
}

class PathNormalizer {
    // Normalize path components by resolving relative segments
    static func normalize(_ path: String) -> String {
        var components = path.components(separatedBy: "/")
        var normalized: [String] = []

        for component in components {
            switch component {
            case ".":
                continue
            case "..":
                if !normalized.isEmpty {
                    normalized.removeLast()
                }
            case "":
                if normalized.isEmpty {
                    normalized.append(component)
                }
            default:
                normalized.append(component)
            }
        }
        return normalized.joined(separator: "/")
    }
}

class FileNameValidator {
    private let config: MigrationConfig

    init(config: MigrationConfig = .default) {
        self.config = config
    }

    // Validates that filename has allowed extension and no null bytes
    func validateFileName(_ name: String) -> Bool {
        guard !name.contains("\0") else { return false }
        guard config.allowedExtensions.contains(where: { name.hasSuffix($0) }) else {
            return false
        }
        return true
    }
}

class MigrationStorageDriver {
    private let config: MigrationConfig
    private let validator: FileNameValidator
    private let normalizer = PathNormalizer.self

    init(config: MigrationConfig = .default) {
        self.config = config
        self.validator = FileNameValidator(config: config)
    }

    // Constructs safe storage path from user-provided filename
    func constructStoragePath(userFileName: String, subDirectory: String?) -> String? {
        // Step 1: Validate the filename
        guard validator.validateFileName(userFileName) else {
            return nil
        }

        // Step 2: Extract just the filename component (strip any directory prefix)
        let sanitizedName = extractFileName(from: userFileName)

        // Step 3: Build the full path
        var fullPath: String
        if let subDir = subDirectory {
            // Normalize the subdirectory to prevent traversal
            let normalizedSubDir = normalizer.normalize(subDir)
            fullPath = config.baseDirectory + "/" + normalizedSubDir + "/" + sanitizedName
        } else {
            fullPath = config.baseDirectory + "/" + sanitizedName
        }

        // Step 4: Final normalization of the complete path
        fullPath = normalizer.normalize(fullPath)

        // Step 5: Verify the final path is within base directory
        guard isWithinBaseDirectory(fullPath) else {
            return nil
        }

        return fullPath
    }

    // Extract filename from potentially full path
    private func extractFileName(from path: String) -> String {
        // Use URL-based extraction for robustness
        if let lastComponent = path.components(separatedBy: "/").last, !lastComponent.isEmpty {
            return lastComponent
        }
        return path
    }

    // Security check: ensure resolved path stays within base directory
    private func isWithinBaseDirectory(_ path: String) -> Bool {
        let resolvedBase = normalizer.normalize(config.baseDirectory) + "/"
        let resolvedPath = normalizer.normalize(path)
        return resolvedPath.hasPrefix(resolvedBase)
    }

    // Process an uploaded migration file
    func processUpload(fileName: String, subDirectory: String?, content: Data) -> Result<String, StorageError> {
        guard content.count <= config.maxFileSize else {
            return .failure(.fileTooLarge)
        }

        guard let storagePath = constructStoragePath(userFileName: fileName, subDirectory: subDirectory) else {
            return .failure(.invalidPath)
        }

        // In production, this would write to disk
        // FileManager.default.createFile(atPath: storagePath, contents: content)
        return .success(storagePath)
    }
}

enum StorageError: Error {
    case invalidPath
    case fileTooLarge
    case writeFailure
}

// HTTP Handler for migration uploads
class MigrationUploadHandler {
    private let storage = MigrationStorageDriver()

    func handleUpload(request: HTTPRequest) -> HTTPResponse {
        guard let fileName = request.headers["X-Migration-Filename"],
              let body = request.body else {
            return HTTPResponse(status: 400, body: "Missing filename or body")
        }

        // The subdirectory comes from a URL-decoded query parameter
        let subDirectory = request.queryParams["dir"]?.removingPercentEncoding

        let result = storage.processUpload(
            fileName: fileName,
            subDirectory: subDirectory,
            content: body
        )

        switch result {
        case .success(let path):
            return HTTPResponse(status: 200, body: "Stored at: \(path)")
        case .failure(let error):
            return HTTPResponse(status: 400, body: "Error: \(error)")
        }
    }
}

// Minimal HTTP types for compilation
struct HTTPRequest {
    let headers: [String: String]
    let body: Data?
    let queryParams: [String: String]
}

struct HTTPResponse {
    let status: Int
    let body: String
}
